/**
 * modules/school/mgmt.js — Management + Facilities & Services API.
 *
 * Mounted INSIDE the school router (router.use("/mgmt", mgmtRouter)) so the
 * audit-trail middleware in routes.js covers every write here too.
 * All data lives in the `mgmt` schema; every row is scoped by school_id.
 *
 * Most endpoints are generated by a small CRUD factory keyed by RESOURCES:
 *   GET    /api/school/mgmt/:resource          list (whitelisted ?field= filters)
 *   POST   /api/school/mgmt/:resource          create
 *   PUT    /api/school/mgmt/:resource/:id      update
 *   DELETE /api/school/mgmt/:resource/:id      delete
 * Custom routes (dashboards, attendance register, fee collection, promote,
 * due slips, carry-forward) are registered BEFORE the generic ones.
 */

import { Router } from "express";
import db from "../../db.js";
import { authenticateToken, requireRole } from "../auth/routes.js";

const router = Router();
const SCHOOL_ROLES = ["school", "school_admin", "admin"];
const M = () => db.schema("mgmt");

async function getMySchool(req, res) {
  const { data } = await db.from("school_profiles").select("id, name")
    .eq("admin_user_id", req.user.id).order("created_at", { ascending: true }).limit(1).maybeSingle();
  if (!data) { res.status(404).json({ error: "No school is linked to this account." }); return null; }
  return data;
}

const studentLabel = (s) => [s.first_name, s.last_name].filter(Boolean).join(" ");

/* ── Resource registry ──────────────────────────────────────────────
   fields: writable columns. refs: fk → {table, label} used to attach
   `<key minus _id>_name` on list rows. filters: query params allowed on list. */
const RESOURCES = {
  // Academics
  "academic-sessions": { table: "academic_sessions", fields: ["name","starts_on","ends_on","is_active"], required: ["name"], orderBy: "starts_on", asc: false },
  "classes":  { table: "classes",  fields: ["name","sort_order"], required: ["name"], orderBy: "sort_order", asc: true },
  "sections": { table: "sections", fields: ["class_id","name"], required: ["class_id","name"], refs: { class_id: ["classes","name"] }, filters: ["class_id"], orderBy: "name", asc: true },
  "subjects": { table: "subjects", fields: ["name","code","subject_type"], required: ["name"], orderBy: "name", asc: true },
  "class-subjects": { table: "class_subjects", fields: ["class_id","subject_id","teacher_id","is_elective"], required: ["class_id","subject_id"], refs: { class_id: ["classes","name"], subject_id: ["subjects","name"] }, filters: ["class_id","is_elective"] },
  "class-teachers": { table: "class_teachers", fields: ["class_id","section_id","teacher_id"], required: ["class_id","teacher_id"], refs: { class_id: ["classes","name"], section_id: ["sections","name"] }, filters: ["class_id"] },
  "periods": { table: "periods", fields: ["name","starts_at","ends_at","sort_order"], required: ["name"], orderBy: "sort_order", asc: true },
  "timetable-slots": { table: "timetable_slots", fields: ["class_id","section_id","day_of_week","period_id","subject_id","teacher_id"], required: ["class_id","day_of_week","period_id"], refs: { class_id: ["classes","name"], section_id: ["sections","name"], period_id: ["periods","name"], subject_id: ["subjects","name"] }, filters: ["class_id","section_id","day_of_week"], orderBy: "day_of_week", asc: true },
  "promotion-logs": { table: "promotion_logs", fields: [], refs: { from_class_id: ["classes","name"], to_class_id: ["classes","name"] }, readOnly: true },

  // Student Information
  "student-categories": { table: "student_categories", fields: ["name"], required: ["name"], orderBy: "name", asc: true },
  "student-houses": { table: "student_houses", fields: ["name","color"], required: ["name"], orderBy: "name", asc: true },
  "students": { table: "students",
    fields: ["admission_no","roll_no","first_name","last_name","gender","dob","class_id","section_id","category_id","house_id","guardian_name","guardian_phone","guardian_email","address","photo_url","blood_group","is_disabled","disability_note","status","admitted_on"],
    required: ["admission_no","first_name","last_name"],
    refs: { class_id: ["classes","name"], section_id: ["sections","name"], category_id: ["student_categories","name"], house_id: ["student_houses","name"] },
    filters: ["class_id","section_id","status","is_disabled","category_id","house_id"] },
  "student-attendance": { table: "student_attendance", fields: ["student_id","date","status","note"], required: ["student_id","date"], refs: { student_id: ["students", studentLabel] }, filters: ["date","student_id","status"], orderBy: "date", asc: false },
  "behavior-records": { table: "behavior_records", fields: ["student_id","incident_type","severity","description","action_taken","recorded_on"], required: ["student_id","incident_type"], refs: { student_id: ["students", studentLabel] }, filters: ["student_id","severity"] },
  "health-records": { table: "health_records", fields: ["student_id","record_type","title","details","recorded_on"], required: ["student_id","title"], refs: { student_id: ["students", studentLabel] }, filters: ["student_id","record_type"] },

  // Finance & Fees
  "fee-groups": { table: "fee_groups", fields: ["name","description"], required: ["name"], orderBy: "name", asc: true },
  "fee-types": { table: "fee_types", fields: ["group_id","name","code","default_amount"], required: ["name"], refs: { group_id: ["fee_groups","name"] }, orderBy: "name", asc: true },
  "fee-discounts": { table: "fee_discounts", fields: ["name","discount_type","amount"], required: ["name"], orderBy: "name", asc: true },
  "fee-assignments": { table: "fee_assignments", fields: ["session_id","fee_type_id","class_id","student_id","amount","due_date","discount_id"], required: ["fee_type_id","amount"], refs: { fee_type_id: ["fee_types","name"], class_id: ["classes","name"], student_id: ["students", studentLabel], discount_id: ["fee_discounts","name"], session_id: ["academic_sessions","name"] }, filters: ["class_id","student_id","session_id","fee_type_id"] },
  "fee-payments": { table: "fee_payments", fields: ["student_id","assignment_id","amount","method","reference","note","paid_on","received_by"], required: ["student_id","amount"], refs: { student_id: ["students", studentLabel] }, filters: ["student_id","method"], orderBy: "paid_on", asc: false },
  "fee-challans": { table: "fee_challans", fields: ["student_id","challan_no","amount","status","due_date"], required: ["student_id","challan_no","amount"], refs: { student_id: ["students", studentLabel] }, filters: ["student_id","status"] },
  "due-slips": { table: "due_slips", fields: [], refs: { student_id: ["students", studentLabel] }, filters: ["student_id"], orderBy: "generated_at", asc: false, readOnly: true },
  "fee-carry-forwards": { table: "fee_carry_forwards", fields: [], refs: { student_id: ["students", studentLabel], from_session_id: ["academic_sessions","name"], to_session_id: ["academic_sessions","name"] }, readOnly: true },

  // Front Office
  "enquiries": { table: "enquiries", fields: ["name","phone","email","class_interest","source","status","note","follow_up_on"], required: ["name"], filters: ["status"] },
  "visitors": { table: "visitors", fields: ["name","phone","purpose","to_meet","id_proof","check_in","check_out"], required: ["name"], orderBy: "check_in", asc: false },
  "complaints": { table: "complaints", fields: ["complainant","phone","category","description","status","action_note"], required: ["complainant"], filters: ["status"] },
  "postal-records": { table: "postal_records", fields: ["direction","reference_no","from_name","to_name","item","note","record_date"], required: ["item"], filters: ["direction"], orderBy: "record_date", asc: false },
};

// Empty strings from <select>/<input> become NULL so uuid/date columns accept them.
function cleanBody(cfg, body) {
  const out = {};
  for (const f of cfg.fields) {
    if (body[f] === undefined) continue;
    out[f] = body[f] === "" ? null : body[f];
  }
  return out;
}

async function attachRefs(cfg, rows, schoolId) {
  if (!cfg.refs || !rows.length) return rows;
  for (const [key, ref] of Object.entries(cfg.refs)) {
    const [table, label] = ref;
    const ids = [...new Set(rows.map((r) => r[key]).filter(Boolean))];
    if (!ids.length) continue;
    const cols = typeof label === "function" ? "*" : `id, ${label}`;
    const { data } = await M().from(table).select(cols).eq("school_id", schoolId).in("id", ids);
    const nameOf = Object.fromEntries((data || []).map((r) => [r.id, typeof label === "function" ? label(r) : r[label]]));
    const outKey = key.replace(/_id$/, "") + "_name";
    for (const row of rows) row[outKey] = row[key] ? (nameOf[row[key]] ?? null) : null;
  }
  return rows;
}

/* ═══════════════ Custom endpoints (registered before generic CRUD) ═══════ */

// ── Dashboards ────────────────────────────────────────────────────────────
router.get("/dashboard/:area", authenticateToken, async (req, res) => {
  try {
    const school = await getMySchool(req, res);
    if (!school) return;
    const count = async (table, apply) => {
      let q = M().from(table).select("id", { count: "exact", head: true }).eq("school_id", school.id);
      if (apply) q = apply(q);
      const { count: c } = await q;
      return c || 0;
    };
    const today = new Date().toISOString().slice(0, 10);
    let data;
    if (req.params.area === "students") {
      data = {
        total: await count("students"),
        active: await count("students", (q) => q.eq("status", "active")),
        disabled: await count("students", (q) => q.eq("is_disabled", true)),
        houses: await count("student_houses"),
        categories: await count("student_categories"),
        presentToday: await count("student_attendance", (q) => q.eq("date", today).eq("status", "present")),
        absentToday: await count("student_attendance", (q) => q.eq("date", today).eq("status", "absent")),
        behaviorIncidents: await count("behavior_records"),
      };
    } else if (req.params.area === "academics") {
      data = {
        sessions: await count("academic_sessions"),
        classes: await count("classes"),
        sections: await count("sections"),
        subjects: await count("subjects"),
        periods: await count("periods"),
        timetableSlots: await count("timetable_slots"),
      };
    } else if (req.params.area === "finance") {
      const { data: pays } = await M().from("fee_payments").select("amount, method, paid_on").eq("school_id", school.id);
      const { data: assigns } = await M().from("fee_assignments").select("amount").eq("school_id", school.id);
      const collected = (pays || []).reduce((s, p) => s + Number(p.amount || 0), 0);
      const assigned = (assigns || []).reduce((s, a) => s + Number(a.amount || 0), 0);
      data = {
        collected, assigned, outstanding: Math.max(0, assigned - collected),
        transactions: (pays || []).length,
        onlineTransactions: (pays || []).filter((p) => p.method === "online").length,
        collectedToday: (pays || []).filter((p) => p.paid_on === today).reduce((s, p) => s + Number(p.amount || 0), 0),
        feeTypes: await count("fee_types"),
      };
    } else if (req.params.area === "front-office") {
      data = {
        enquiries: await count("enquiries"),
        openEnquiries: await count("enquiries", (q) => q.eq("status", "new")),
        visitorsToday: await count("visitors", (q) => q.gte("check_in", `${today}T00:00:00Z`)),
        openComplaints: await count("complaints", (q) => q.neq("status", "resolved")),
        postalRecords: await count("postal_records"),
      };
    } else return res.status(404).json({ error: "Unknown dashboard area" });
    res.json({ success: true, data });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Attendance register: students of a class/section + that day's marks ──
router.get("/attendance/register", authenticateToken, async (req, res) => {
  try {
    const school = await getMySchool(req, res);
    if (!school) return;
    const { class_id, section_id, date } = req.query;
    if (!class_id || !date) return res.status(400).json({ error: "class_id and date are required" });
    let q = M().from("students").select("id, admission_no, roll_no, first_name, last_name")
      .eq("school_id", school.id).eq("class_id", class_id).eq("status", "active").order("roll_no", { ascending: true });
    if (section_id) q = q.eq("section_id", section_id);
    const { data: students } = await q;
    const ids = (students || []).map((s) => s.id);
    const { data: marks } = ids.length
      ? await M().from("student_attendance").select("student_id, status, note").eq("date", date).in("student_id", ids)
      : { data: [] };
    const markOf = Object.fromEntries((marks || []).map((m) => [m.student_id, m]));
    res.json({ success: true, data: (students || []).map((s) => ({
      ...s, name: studentLabel(s), status: markOf[s.id]?.status || null, note: markOf[s.id]?.note || null,
    })) });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Mark attendance (bulk upsert) ─────────────────────────────────────────
router.post("/attendance/mark", authenticateToken, requireRole(SCHOOL_ROLES), async (req, res) => {
  try {
    const school = await getMySchool(req, res);
    if (!school) return;
    const { date, entries } = req.body;
    if (!date || !Array.isArray(entries) || !entries.length) return res.status(400).json({ error: "date and entries[] are required" });
    const rows = entries.filter((e) => e.student_id && e.status).map((e) => ({
      school_id: school.id, student_id: e.student_id, date, status: e.status, note: e.note || null,
    }));
    const { error } = await M().from("student_attendance").upsert(rows, { onConflict: "student_id,date" });
    if (error) throw new Error(error.message);
    res.json({ success: true, marked: rows.length });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Promote students (bulk move class → class) ────────────────────────────
router.post("/students/promote", authenticateToken, requireRole(SCHOOL_ROLES), async (req, res) => {
  try {
    const school = await getMySchool(req, res);
    if (!school) return;
    const { from_class_id, to_class_id, session_id, student_ids } = req.body;
    if (!from_class_id || !to_class_id) return res.status(400).json({ error: "from_class_id and to_class_id are required" });
    let q = M().from("students").update({ class_id: to_class_id, section_id: null })
      .eq("school_id", school.id).eq("class_id", from_class_id);
    if (Array.isArray(student_ids) && student_ids.length) q = q.in("id", student_ids);
    const { data, error } = await q.select("id");
    if (error) throw new Error(error.message);
    await M().from("promotion_logs").insert({
      school_id: school.id, from_class_id, to_class_id, session_id: session_id || null, student_count: (data || []).length,
    });
    res.json({ success: true, promoted: (data || []).length });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Fee dues: assigned − paid per student ─────────────────────────────────
async function computeDues(schoolId, { student_id, class_id } = {}) {
  let sq = M().from("students").select("id, admission_no, first_name, last_name, class_id").eq("school_id", schoolId).eq("status", "active");
  if (student_id) sq = sq.eq("id", student_id);
  if (class_id) sq = sq.eq("class_id", class_id);
  const { data: students } = await sq;
  if (!students?.length) return [];
  const classIds = [...new Set(students.map((s) => s.class_id).filter(Boolean))];
  const { data: assigns } = await M().from("fee_assignments")
    .select("id, class_id, student_id, amount, fee_type_id").eq("school_id", schoolId);
  const { data: pays } = await M().from("fee_payments").select("student_id, amount").eq("school_id", schoolId);
  const paidOf = {};
  for (const p of pays || []) paidOf[p.student_id] = (paidOf[p.student_id] || 0) + Number(p.amount || 0);
  return students.map((s) => {
    const assigned = (assigns || [])
      .filter((a) => a.student_id === s.id || (a.class_id && a.class_id === s.class_id && !a.student_id))
      .reduce((sum, a) => sum + Number(a.amount || 0), 0);
    const paid = paidOf[s.id] || 0;
    return { student_id: s.id, admission_no: s.admission_no, name: studentLabel(s), assigned, paid, due: Math.max(0, assigned - paid) };
  });
}

router.get("/fees/dues", authenticateToken, async (req, res) => {
  try {
    const school = await getMySchool(req, res);
    if (!school) return;
    const rows = await computeDues(school.id, { student_id: req.query.student_id, class_id: req.query.class_id });
    res.json({ success: true, data: rows });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Collect a fee payment ─────────────────────────────────────────────────
router.post("/fees/collect", authenticateToken, requireRole(SCHOOL_ROLES), async (req, res) => {
  try {
    const school = await getMySchool(req, res);
    if (!school) return;
    const { student_id, assignment_id, amount, method = "cash", reference, note } = req.body;
    if (!student_id || !amount) return res.status(400).json({ error: "student_id and amount are required" });
    const { data, error } = await M().from("fee_payments").insert({
      school_id: school.id, student_id, assignment_id: assignment_id || null,
      amount, method, reference: reference || `RCPT-${Date.now().toString(36).toUpperCase()}`,
      note: note || null, received_by: req.user.fullName || req.user.email,
    }).select("*").single();
    if (error) throw new Error(error.message);
    res.status(201).json({ success: true, data });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Generate due slips for a class (one per student with a balance) ──────
router.post("/fees/due-slips/generate", authenticateToken, requireRole(SCHOOL_ROLES), async (req, res) => {
  try {
    const school = await getMySchool(req, res);
    if (!school) return;
    const { class_id, period_label } = req.body;
    if (!class_id) return res.status(400).json({ error: "class_id is required" });
    const dues = (await computeDues(school.id, { class_id })).filter((d) => d.due > 0);
    if (!dues.length) return res.json({ success: true, generated: 0, message: "No outstanding dues in that class." });
    const stamp = Date.now().toString(36).toUpperCase();
    const rows = dues.map((d, i) => ({
      school_id: school.id, student_id: d.student_id, slip_no: `DS-${stamp}-${i + 1}`,
      period_label: period_label || null, amount_due: d.due,
    }));
    const { error } = await M().from("due_slips").insert(rows);
    if (error) throw new Error(error.message);
    res.status(201).json({ success: true, generated: rows.length });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Carry unpaid balances into a new session ──────────────────────────────
router.post("/fees/carry-forward", authenticateToken, requireRole(SCHOOL_ROLES), async (req, res) => {
  try {
    const school = await getMySchool(req, res);
    if (!school) return;
    const { from_session_id, to_session_id } = req.body;
    if (!from_session_id || !to_session_id) return res.status(400).json({ error: "from_session_id and to_session_id are required" });
    const dues = (await computeDues(school.id)).filter((d) => d.due > 0);
    if (!dues.length) return res.json({ success: true, carried: 0, message: "No outstanding balances to carry forward." });
    const { error } = await M().from("fee_carry_forwards").insert(dues.map((d) => ({
      school_id: school.id, student_id: d.student_id, from_session_id, to_session_id, amount: d.due,
    })));
    if (error) throw new Error(error.message);
    res.status(201).json({ success: true, carried: dues.length });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

/* ═══════════════════════ Generic CRUD ════════════════════════════════════ */

router.get("/:resource", authenticateToken, async (req, res) => {
  try {
    const cfg = RESOURCES[req.params.resource];
    if (!cfg) return res.status(404).json({ error: "Unknown resource" });
    const school = await getMySchool(req, res);
    if (!school) return;
    let q = M().from(cfg.table).select("*").eq("school_id", school.id)
      .order(cfg.orderBy || "created_at", { ascending: cfg.asc ?? false }).limit(500);
    for (const f of cfg.filters || []) {
      if (req.query[f] !== undefined && req.query[f] !== "") q = q.eq(f, req.query[f]);
    }
    const { data, error } = await q;
    if (error) throw new Error(error.message);
    res.json({ success: true, data: await attachRefs(cfg, data || [], school.id) });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

router.post("/:resource", authenticateToken, requireRole(SCHOOL_ROLES), async (req, res) => {
  try {
    const cfg = RESOURCES[req.params.resource];
    if (!cfg || cfg.readOnly) return res.status(404).json({ error: "Unknown resource" });
    const school = await getMySchool(req, res);
    if (!school) return;
    const body = cleanBody(cfg, req.body);
    for (const f of cfg.required || []) {
      if (body[f] === undefined || body[f] === null || body[f] === "") return res.status(400).json({ error: `${f} is required` });
    }
    const { data, error } = await M().from(cfg.table).insert({ ...body, school_id: school.id }).select("*").single();
    if (error) {
      if (error.code === "23505") return res.status(409).json({ error: "A record with those unique values already exists" });
      throw new Error(error.message);
    }
    res.status(201).json({ success: true, data: (await attachRefs(cfg, [data], school.id))[0] });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

router.put("/:resource/:id", authenticateToken, requireRole(SCHOOL_ROLES), async (req, res) => {
  try {
    const cfg = RESOURCES[req.params.resource];
    if (!cfg || cfg.readOnly) return res.status(404).json({ error: "Unknown resource" });
    const school = await getMySchool(req, res);
    if (!school) return;
    const body = cleanBody(cfg, req.body);
    if (!Object.keys(body).length) return res.status(400).json({ error: "No valid fields to update" });
    const { data, error } = await M().from(cfg.table).update(body)
      .eq("id", req.params.id).eq("school_id", school.id).select("*").single();
    if (error) {
      if (error.code === "23505") return res.status(409).json({ error: "A record with those unique values already exists" });
      throw new Error(error.message);
    }
    res.json({ success: true, data: (await attachRefs(cfg, [data], school.id))[0] });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

router.delete("/:resource/:id", authenticateToken, requireRole(SCHOOL_ROLES), async (req, res) => {
  try {
    const cfg = RESOURCES[req.params.resource];
    if (!cfg) return res.status(404).json({ error: "Unknown resource" });
    const school = await getMySchool(req, res);
    if (!school) return;
    const { error } = await M().from(cfg.table).delete().eq("id", req.params.id).eq("school_id", school.id);
    if (error) throw new Error(error.message);
    res.json({ success: true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

export default router;
